from pathlib import Path
import json,os,sys,subprocess,time,hashlib,signal
import rclpy
from std_msgs.msg import String
root=Path('/tmp/textbook-clion-gui');stage=sys.argv[1]
proc=None
if len(sys.argv)>2:
    proc=subprocess.Popen(sys.argv[2:],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
rclpy.init(); node=rclpy.create_node('textbook_probe_'+stage);values=[]
sub=node.create_subscription(String,'/status',lambda msg:values.append(msg.data),10)
start=time.monotonic()
while len(values)<3 and time.monotonic()-start<8:rclpy.spin_once(node,timeout_sec=.2)
node.destroy_node();rclpy.shutdown()
obj={'stage':stage,'elapsed':time.monotonic()-start,'values':values,'domain':os.environ.get('ROS_DOMAIN_ID'),'range':os.environ.get('ROS_AUTOMATIC_DISCOVERY_RANGE')}
if proc:
    os.killpg(proc.pid,signal.SIGTERM)
    try:stdout,stderr=proc.communicate(timeout=3)
    except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);stdout,stderr=proc.communicate()
    obj.update(argv=sys.argv[2:],returncode=proc.returncode,stdout=stdout,stderr=stderr)
with (root/'ros-probes.jsonl').open('a') as f:f.write(json.dumps(obj)+'\n')
print(json.dumps(obj))
if len(values)<3:sys.exit(1)
